// Resend sends { type: 'email.delivered', data: { email_id, to, ... } }.
// Map to our vocabulary and drop anything we do not model rather than writing junk.
const MAP = {
  'email.sent': 'sent',
  'email.delivered': 'delivered',
  'email.opened': 'opened',
  'email.clicked': 'clicked',
  'email.bounced': 'bounced',
  'email.complained': 'complained',
  'email.delivery_delayed': null
};

const out = [];
for (const item of $input.all()) {
  const b = item.json.body || item.json;
  const event = MAP[b.type];
  if (!event) continue;
  const messageId = b.data?.email_id || b.data?.id || null;
  if (!messageId) continue;
  out.push({ json: { event, messageId, raw: b } });
}
return out;
